{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE hox_db.maplemonk.HOX_DB_YFLHOME_PAYMENT_RECON_CONSOLIDATED_2026 AS WITH COD_orders AS ( SELECT REFERENCE_CODE, date(order_date) AS ORDER_DATE, CUSTOMER_ID, MARKETPLACE, ORDER_ID, ORDER_STATUS, PAYMENT_MODE, SUM(QUANTITY), SUM(SELLING_PRICE) AS CX_RECEIVED_AMOUNT, COUNT(REFERENCE_CODE) AS SKU_COUNT FROM hox_db.maplemonk.HOX_DB_YFLHOME_SALES_CONSOLIDATED WHERE upper(SHOP_NAME)=\'SHOPIFY_YFLHOME\' AND upper(PAYMENT_MODE)=\'COD\' AND date(order_date) between \'2024-06-01\' and \'2026-03-31\' GROUP BY 1,2,3,4,5,6,7 order by 2 desc ), CLICKPOST_DATA AS ( SELECT *, LENGTH(product_sku_code) - LENGTH(REPLACE(product_sku_code, \',\', \'\')) + 1 AS SKU_COUNT FROM ( SELECT order_id, order_date, PAYMENT_MODE, created_at, Final_Status, Courier_Partner, SUM(Clickpost_Amount) AS Clickpost_Amount, LISTAGG(product_sku_code,\',\') AS product_sku_code, FROM ( SELECT a.order_id, a.created_at, a.order_date, a.payment_mode, CASE WHEN UPPER(a.clickpost_unified_status) in (\'RTO-FAILED\',\'RTO-MARKED\',\'RTO-INTRANSIT\',\'RTO-DELIVERED\') THEN \'RTO\' WHEN UPPER(a.clickpost_unified_status) in (\'OUTFORPICKUP\',\'ORDERPLACED\') THEN \'OrderPlaced\' WHEN UPPER(a.clickpost_unified_status) in (\'FAILEDDELIVERY\',\'DESTINATIONHUBIN\') THEN \'InTransit\' ELSE a.clickpost_unified_status END AS Final_Status, IFNULL(CAST(REPLACE(a.cod_value,\',\',\'\') AS INT),0) as Clickpost_Amount, a.courier_partner as Courier_Partner, a.product_sku_code FROM hox_db.maplemonk.payment_recon_clickpost a order by 2 desc ) AS x GROUP BY 1,2,3,4,5,6 ) AS y order by 2 desc ), COD_BASE AS ( SELECT co.*, abc.order_id, abc.created_at, abc.Courier_Partner, abc.product_sku_code, abc.Clickpost_Amount AS Total_Received, abc.SKU_COUNT, CASE WHEN abc.Final_Status IS NULL then co.ORDER_STATUS else abc.Final_Status end as Final_Status FROM COD_orders co LEFT JOIN CLICKPOST_DATA abc ON RIGHT(co.REFERENCE_CODE,LENGTH(co.REFERENCE_CODE)-LENGTH(\'#\'))=abc.order_id and co.SKU_COUNT=abc.SKU_COUNT ), Final_Report_Cod as ( SELECT DATE_TRUNC(\'month\', ORDER_DATE) AS month_start, COURIER_PARTNER, sum(CX_RECEIVED_AMOUNT) as TOTAL_CX_PAID, sum(TOTAL_RECEIVED) AS TOTAL_AMOUNT_RECEIVED, sum(CX_RECEIVED_AMOUNT-TOTAL_RECEIVED) AS TOTAL_DIFFFERENCE FROM COD_BASE WHERE COURIER_PARTNER IS NOT NULL AND UPPER(FINAL_STATUS) IN (\'DELIVERED\',\'SHOPIFY_PROCESSED\') GROUP BY 1,2 ORDER BY 1 DESC ), Easyecom as ( SELECT REFERENCE_CODE, ORDER_DATE, COURIER,ORDER_STATUS, SHIPPING_STATUS FROM Hox_db.maplemonk.easyecom_yflhome_customer_orders WHERE lower(marketplace) in (\'shopify\',\'offline\') and date(order_date) between \'2024-06-01\' and \'2026-03-31\' ), Prepaid_orders AS ( SELECT a.REFERENCE_CODE, date(a.order_date) AS ORDER_DATE, a.CUSTOMER_ID, a.MARKETPLACE, a.ORDER_STATUS, a.PAYMENT_MODE, a.QUANTITY, a.SELLING_PRICE, b.shadow_id, b.order_id, RIGHT(a.REFERENCE_CODE,LENGTH(a.REFERENCE_CODE)-LENGTH(\'#\')) as ORDER_NUM FROM hox_db.maplemonk.HOX_DB_YFLHOME_SALES_CONSOLIDATED a LEFT JOIN hox_db.maplemonk.payment_recon_db b on a.REFERENCE_CODE=b.name WHERE upper(a.SHOP_NAME)=\'SHOPIFY_YFLHOME\' AND upper(a.PAYMENT_MODE)=\'PREPAID\' AND date(a.order_date) between \'2024-06-01\' and \'2026-03-31\' ), Simpl as (SELECT *, LEFT(c.order_id,LENGTH(c.order_id)-LEN(\'-1\')) AS pre_final_shadowId, RIGHT(pre_final_shadowId,LENGTH(LEFT(c.order_id,LENGTH(c.order_id)-LENGTH(\'-1\')))-LENGTH(\'houseofx-\')) as final_shadow_Id FROM HOX_DB.MAPLEMONK.payment_recon_simpl c ), PREPAID_BASE AS ( SELECT *, CASE WHEN (lower(SHIPPING_STATUS)=\'delivered\' OR lower(FINAL_STATUS)=\'delivered\' OR upper(FINAL_STATUS)=\'SHOPIFY_PROCESSED\') AND (SHIPPING_STATUS IS NOT NULL) THEN \'Delivered\' ELSE \'Other\' END AS Final_Shipping_Status FROM ( SELECT DISTINCT po.*, cte.db_amount, cte.PhonePe_amount, cte.Simpl_amount, cte.snapmint_amount, cte.gateway as payment_gateway, e.courier, e.order_status, e.shipping_status, CASE WHEN clickpost.clickpost_unified_status is NULL then po.ORDER_STATUS WHEN UPPER(clickpost.clickpost_unified_status) in (\'RTO-FAILED\',\'RTO-MARKED\',\'RTO-INTRANSIT\',\'RTO-DELIVERED\') THEN \'RTO\' WHEN UPPER(clickpost.clickpost_unified_status) in (\'OUTFORPICKUP\',\'ORDERPLACED\') THEN \'OrderPlaced\' WHEN UPPER(clickpost.clickpost_unified_status) in (\'FAILEDDELIVERY\',\'DESTINATIONHUBIN\') THEN \'InTransit\' ELSE clickpost.clickpost_unified_status END AS Final_Status FROM Prepaid_orders po LEFT JOIN ( SELECT a.shadow_id, a.gateway, IFNULL(CAST(REPLACE(a.amount,\',\',\'\') AS INT),0) as db_amount, IFNULL(CAST(REPLACE(b.Total_Transaction_Amount,\',\',\'\') AS INT),0) as PhonePe_amount, IFNULL(CAST(REPLACE(c.net_amount_rs_,\',\',\'\') AS INT),0) as Simpl_amount, IFNULL(CAST(REPLACE(s.settlement_value,\',\',\'\') AS INT),0) as snapmint_amount FROM HOX_DB.MAPLEMONK.payment_recon_db a LEFT JOIN HOX_DB.MAPLEMONK.payment_recon_phonepe b on a.shadow_id=b.final_shadow_Id LEFT JOIN Simpl c on a.shadow_id=c.final_shadow_Id LEFT JOIN HOX_DB.MAPLEMONK.PAYMENT_RECON_SNAPMINT s on a.shadow_id=s.order_no_ ) as cte on po.shadow_id=cte.shadow_id LEFT JOIN HOX_DB.MAPLEMONK.payment_recon_clickpost clickpost on po.ORDER_NUM =clickpost.order_id LEFT JOIN Hox_db.maplemonk.easyecom_yflhome_customer_orders e on po.ORDER_NUM=e.reference_code ) ), Prepaid_Base_with_rank as ( SELECT distinct * FROM ( SELECT distinct REFERENCE_CODE, ORDER_DATE, CUSTOMER_ID, MARKETPLACE, PAYMENT_MODE, QUANTITY, SELLING_PRICE, SHADOW_ID, ORDER_ID, ORDER_NUM, DB_AMOUNT, PHONEPE_AMOUNT, PAYMENT_GATEWAY, SIMPL_AMOUNT, SNAPMINT_AMOUNT, FINAL_SHIPPING_STATUS FROM PREPAID_BASE WHERE lower(Final_Shipping_Status)=\'delivered\' ) as x ), PREPAID_FINAL AS ( SELECT *, PHONEPE_AMOUNT+SIMPL_AMOUNT+SNAPMINT_AMOUNT AS TOTAL_RECEIVED FROM ( SELECT DISTINCT a.ORDER_ID, a.ORDER_DATE, CAST(REPLACE(b.TOTAL_SALES,\',\',\'\') AS INT) AS AMOUNT, a.PAYMENT_GATEWAY, IFNULL(a.DB_AMOUNT,0) AS DB_AMOUNT, IFNULL(a.PHONEPE_AMOUNT,0) AS PHONEPE_AMOUNT, IFNULL(a.SIMPL_AMOUNT,0) AS SIMPL_AMOUNT, IFNULL(a.SNAPMINT_AMOUNT,0) AS SNAPMINT_AMOUNT FROM PREPAID_BASE_with_rank a LEFT JOIN ( SELECT ORDER_ID, SUM(SELLING_PRICE) AS TOTAL_SALES FROM PREPAID_BASE_with_rank GROUP BY 1 ) b ON a.ORDER_ID=b.ORDER_ID ) as a ), Final_Report_Prepaid as ( SELECT *, CX_PAID-TOTAL_RECEIVED AS DIFFERENCE FROM ( SELECT DATE_TRUNC(\'month\', ORDER_DATE) AS month_start, PAYMENT_GATEWAY, SUM(AMOUNT) AS CX_PAID, SUM(TOTAL_RECEIVED) AS TOTAL_RECEIVED FROM PREPAID_FINAL WHERE PAYMENT_GATEWAY IS NOT NULL GROUP BY 1,2 ORDER BY 1 ASC ) AS x ) SELECT * FROM Final_Report_Prepaid UNION SELECT * FROM Final_Report_COD order by 1 desc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from HOX_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            